def split(lang):
    i = 0 if lang == "en" else 1
    return {ns: {k: v[i] for k, v in d.items()} for ns, d in T.items()}

out = os.path.join(os.path.dirname(__file__), "..", "src", "messages")
for lang in ("en", "sw"):
    with open(os.path.join(out, f"{lang}.json"), "w", encoding="utf-8") as f:
        json.dump(split(lang), f, ensure_ascii=False, indent=2)
        f.write("\n")
print("messages written")
